from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.cell_lock.classical_cell_lock.cell_lock_prototype import CellLock
from taf.ul.kpi_selector.operations.cell_lock.classical_cell_lock.cell_lock_23R1 import CellLock23R1


class CellLockFactory(OperationFactoryPrototype):
    def __init__(self):
        super(CellLockFactory, self).__init__()

    def get_kpi(self):
        """
        Gets kpi for cell lock operation.
        :return: dictionary with timeout, requirement and operation description for cell lock
        :rtype: dict
        """
        if self.bts.stream >= "SBTS23R1":
            return CellLock23R1(self.bts).get_kpi()
        else:
            return CellLock(self.bts).get_kpi()
